\label{geo:cluster}
\label{geo:phaseseparation}
Let $\Gamma$ be a nonempty union of finitely many periodic flow orbits whose total period, after removing repeated copies, is at most $C_0T$, where $T\geqslant1$ and $C_0$ is fixed. The constants may also depend on $C_0$. For every integer $m\geqslant1$, there are sections $E_i\Subset D_i$, containing the cores $K_i$, a nonempty subset $\mathcal C$ of $S:=\Gamma\cap\bigcup_iE_i$, and a point $z\in\mathcal C$ such that
\begin{equation}
 \#\mathcal C\leqslant m,\qquad \operatorname{dist}_{E_i}\bigl(z,(S\cap E_i)\setminus\mathcal C\bigr)\geqslant\delta,\qquad \delta=c(1+T)^{-1}e^{-CT/m},
 \label{geo:sparseball}
\end{equation}
where $E_i$ contains $z$, and its distance is taken in the fixed disk coordinates. The ball $B_{E_i}(z,\delta)$ lies in the interior of $E_i$. We call the elements of $\mathcal C$ the \emph{extreme neighbours} of $z$, including $z$ itself. Moreover, distinct hits satisfy
\begin{equation}
 \operatorname{dist}(z,w)\geqslant c(1+T)^{-1}e^{-CT},\qquad z,w\in S,\quad z\ne w.
 \label{geo:hitsep}
\end{equation}
Two distinct oriented geometric periodic orbits of periods at most $T$ also have phase-space distance at least $c(1+T)^{-1}e^{-CT}$.

\label{geo:graphs}
On a fixed sufficiently short interval $I$, let two nearby geodesic arcs be written as graphs in a smooth chart, with bounded slopes, and let $b:I\to\mathbb R^{\dim M-1}$ be their difference. Then
\begin{equation}
 b''=U(t)b+V(t)b',\qquad \left\|U\right\|_{C^0}+\left\|V\right\|_{C^0}\leqslant C.
 \label{geo:graphode}
\end{equation}
If $|b(t)|+|b'(t)|\geqslant q$ on $I$ and $0<a<cq$, then
\begin{equation}
 \bigl|\{t\in I:|b(t)|<a\}\bigr|\leqslant Ca/q.
 \label{geo:sublevel}
\end{equation}
The interval length and the constants are uniform in $\operatorname{{\mathscr U}}$.

\label{geo:detector}
Let $k\geqslant3$, $\left\|g\right\|_{C^k}\leqslant B$, and let $\gamma\ne\eta$ be closed geodesics, with repetitions allowed, of lengths at most $T\geqslant1$. For every integer $m\geqslant1$, there is $f\in C^k(M)$ such that
\begin{equation}
 \left\|f\right\|_{C^k}\leqslant1,\qquad \left|\left.\frac{d}{ds}\bigl(\ell_{g_s}(\gamma_s)-\ell_{g_s}(\eta_s)\bigr)\right|_{s=0}\right|\geqslant c_{k,m,B}e^{-C(m+k/m)T}.
 \label{geo:detectorbound}
\end{equation}
Here $g_s$ is given by~\eqref{geo:conformal}, and $\gamma_s,\eta_s$ are the geodesics in the corresponding classes. If their geometric images are distinct, $f$ can be chosen nonnegative, supported in one coordinate chart, with $f=df=0$ on one of them.

\label{prob:jackson}
There is a fixed countable collection of smooth real functions $e_j$ on $M$, with frequencies $\nu_j\geqslant1$, such that
\begin{equation}
 \#\{j:\nu_j\leqslant N\}\leqslant C N^n,\qquad \left\|e_j\right\|_{C^a}\leqslant C_a\nu_j^a.
 \label{prob:modes}
\end{equation}
For every $f\in C^k(M)$ and $N\geqslant2$, there is a finite combination $f_N=\sum_{\nu_j\leqslant CN}b_j e_j$ satisfying
\begin{equation}
 |b_j|\leqslant C\left\|f\right\|_{C^0},\qquad \left\|f-f_N\right\|_{C^0}\leqslant C_k N^{-k}\left\|f\right\|_{C^k}.
 \label{prob:jackson-estimate}
\end{equation}

\label{prob:second-variation}
Let $g_t$ be a twice differentiable path of $C^k$ metrics in the fixed geometric neighborhood. Then
\begin{equation}
 \left|\frac{d^2}{dt^2}\ell_{g_t}(\gamma)\right|\leqslant C_h\ell_{g_t}(\gamma)\bigl(\left\|\partial_tg_t\right\|_{C^1}^2+\left\|\partial_t^2g_t\right\|_{C^0}\bigr).
 \label{prob:hessian}
\end{equation}
The same estimate holds for iterated closed geodesics.

\label{prob:pair}
Suppose a translated family $g+v_\xi$ from~\eqref{prob:probe} is entirely contained in a bounded $C^k$-family in the geometric neighborhood. Fix two different geometric closed geodesics, allowing repetitions, whose lengths are at most $T\geqslant1$ for every parameter. Then
\begin{equation}
 \mathbb P\left\{|\ell_{g+v_\xi}(\gamma)-\ell_{g+v_\xi}(\eta)|<a\right\}\leqslant C_{k,\varepsilon}a\exp(C_h\sqrt{k}\,T),\qquad a>0.
 \label{prob:pair-bound}
\end{equation}
The prefactor may depend on the $C^k$ bound. The exponent constant depends only on the fixed geometric neighborhood, dimension, and the constants in Proposition~\ref{geo:detector}.

\label{prob:gaps}
There is $B=B(h)>0$, independent of $k\geqslant3$, such that almost every metric in every translated probe family as in Proposition~\ref{prob:pair} satisfies
\begin{equation}
 |\ell_g(\gamma)-\ell_g(\eta)|\geqslant c(g)\exp\left[-B\sqrt{k}\max\{\ell_g(\gamma),\ell_g(\eta)\}\right]
 \label{prob:gap-property}
\end{equation}
for all different unoriented free homotopy classes, with some $c(g)>0$.
